package app.kinnect.audit;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import android.graphics.*;import java.io.*;import java.lang.reflect.*;import org.json.*;
public class LiveRedesignAudit extends Instrumentation {
 public void onCreate(Bundle b){super.onCreate(b);start();}void check(boolean ok,String why){if(!ok)throw new AssertionError(why);}
 Object call(Object a,String name,Class<?>[] types,Object...args)throws Exception{Method m=a.getClass().getDeclaredMethod(name,types);m.setAccessible(true);return m.invoke(a,args);}Object get(Object a,String key)throws Exception{Field f=a.getClass().getDeclaredField(key);f.setAccessible(true);return f.get(a);}void set(Object a,String key,Object value)throws Exception{Field f=a.getClass().getDeclaredField(key);f.setAccessible(true);f.set(a,value);}
 void shot(Activity a,String name)throws Exception{waitForIdleSync();Thread.sleep(300);if(!name.contains("guests")&&!name.contains("choice"))check(a.hasWindowFocus(),"Screen obscured: "+name);try(FileOutputStream f=new FileOutputStream(new File(a.getExternalFilesDir(null),name))){getUiAutomation().takeScreenshot().compress(Bitmap.CompressFormat.PNG,100,f);}}
 void fonts(View v)throws Exception{if(v instanceof TextView){TextView t=(TextView)v;String text=t.getText().toString();if(text.codePoints().anyMatch(Character::isLetterOrDigit)){Class<?> family=t.getContext().getClassLoader().loadClass("app.kinnect.live.ApprovedTypography");Method font=family.getDeclaredMethod("font",Context.class,int.class);font.setAccessible(true);int style=t.getTypeface()==null?0:t.getTypeface().getStyle();check(t.getTypeface().equals(font.invoke(null,t.getContext(),style)),"Mixed typeface: "+text);float size=t.getTextSize()/t.getResources().getDisplayMetrics().scaledDensity;check(size<=("sheet:title".equals(t.getTag())?17.1f:14.1f),"Sheet font too large: "+text);}}if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++)fonts(g.getChildAt(i));}}
 public void onStart(){Bundle out=new Bundle();try{Class<?> language=getTargetContext().getClassLoader().loadClass("app.kinnect.live.I18n");Method select=language.getDeclaredMethod("select",Context.class,String.class);select.setAccessible(true);select.invoke(null,getTargetContext(),"vi");getTargetContext().getSharedPreferences("native_setup",0).edit().putBoolean("asked_v1",true).commit();Activity a=startActivitySync(new Intent().setClassName("app.kinnect.live","app.kinnect.live.LiveActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Thread.sleep(1200);runOnMainSync(()->{try{Object socket=get(a,"socket");if(socket!=null)call(socket,"close",new Class[]{});set(a,"socket",null);set(a,"config",new JSONObject().put("iceServers",new JSONArray()));set(a,"joined",true);JSONObject room=new JSONObject().put("id","local-layout-audit").put("host","Chủ phòng").put("hostId","audit-host").put("title","Cùng nhau lên Live").put("viewers",12);call(a,"showRoom",new Class[]{JSONObject.class},new JSONObject().put("room",room));JSONArray participants=new JSONArray().put(new JSONObject().put("id","host").put("userId","h").put("name","Chủ phòng").put("role","host").put("mode","video")).put(new JSONObject().put("id","guest").put("userId","g").put("name","Khách mời").put("role","guest").put("mode","audio"));JSONObject state=new JSONObject().put("room","local-layout-audit").put("selfId","viewer").put("role","viewer").put("revision",1).put("layout","panel").put("participants",participants).put("peers",new JSONArray());call(a,"applyLiveStage",new Class[]{JSONObject.class},state);call(a,"addChat",new Class[]{String.class,String.class},"Minh Anh","Chào cả phòng 👋");call(a,"showArrival",new Class[]{String.class},"Ngọc Linh");}catch(Exception e){throw new RuntimeException(e);}});waitForIdleSync();Thread.sleep(500);runOnMainSync(()->{try{ViewGroup board=(ViewGroup)get(a,"liveBoard");check(board.getChildCount()==2,"Guest tiles missing");View first=board.getChildAt(0),second=board.getChildAt(1);Rect x=new Rect(first.getLeft(),first.getTop(),first.getRight(),first.getBottom()),y=new Rect(second.getLeft(),second.getTop(),second.getRight(),second.getBottom());check(!Rect.intersects(x,y)&&x.height()>100&&y.width()>60,"Live tiles overlap");call(a,"liveTools",new Class[]{});check(get(a,"liveTray") instanceof HorizontalScrollView,"Tools must open horizontally");}catch(Exception e){throw new RuntimeException(e);}});shot(a,"live17-native-tools.png");runOnMainSync(()->{try{call(a,"gifts",new Class[]{});check(get(a,"openTray").equals("gifts"),"Gift tray did not replace tools");ViewGroup stage=(ViewGroup)get(a,"liveStage");int trays=0;for(int i=0;i<stage.getChildCount();i++)if(stage.getChildAt(i) instanceof HorizontalScrollView)trays++;check(trays==1,"Multiple horizontal trays stacked");}catch(Exception e){throw new RuntimeException(e);}});shot(a,"live17-native-gifts.png");runOnMainSync(()->{try{set(a,"host",true);set(a,"guestUsers",new JSONArray().put(new JSONObject().put("id","guest").put("name","Khách mời").put("onStage",true)));call(a,"guestManagement",new Class[]{});Dialog sheet=(Dialog)get(a,"guestSheet");fonts(sheet.getWindow().getDecorView());}catch(Exception e){throw new RuntimeException(e);}});shot(a,"live17-native-guests.png");runOnMainSync(()->{try{((Dialog)get(a,"guestSheet")).dismiss();a.finish();}catch(Exception e){throw new RuntimeException(e);}});
 Activity main=startActivitySync(new Intent().setClassName("app.kinnect.live","app.kinnect.live.MainActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Thread.sleep(600);File clip=new File(main.getExternalFilesDir(null),"audit-short.mp4");try(InputStream in=getContext().getAssets().open("audit-short.mp4");FileOutputStream f=new FileOutputStream(clip)){byte[] bytes=new byte[8192];for(int n;(n=in.read(bytes))!=-1;)f.write(bytes,0,n);}final Dialog[] chooser={null};runOnMainSync(()->{try{chooser[0]=(Dialog)call(main,"uploadVideo",new Class[]{android.net.Uri.class},android.net.Uri.fromFile(clip));fonts(chooser[0].getWindow().getDecorView());}catch(Exception e){throw new RuntimeException(e);}});shot(main,"live17-native-video-choice.png");runOnMainSync(()->{chooser[0].dismiss();main.finish();});out.putString("result","PASS: native live board and audio guest tile; horizontal tools/gifts are mutually exclusive; guest sheet and video route chooser use the bundled family and compact text sizes");finish(Activity.RESULT_OK,out);
 }catch(Throwable error){out.putString("error",error.toString());finish(Activity.RESULT_CANCELED,out);}}
}
